import { PixelImage } from './pixel-art';

/** Píxeles RGBA de las referencias adjuntas, codificados en paleta para no depender de archivos externos. */
export const SMALL_FORGE_WIDTH = 34;
export const SMALL_FORGE_HEIGHT = 46;
const smallPalette =
  '';
const smallPixels =
  '';

export const LARGE_FORGE_WIDTH = 78;
export const LARGE_FORGE_HEIGHT = 102;
const largePalette =
  '';
const largePixels =
  '';

export const HANGER_WIDTH = 34;
export const HANGER_HEIGHT = 37;
const hangerPalette =
  'AAAAEAgIGAAAGAgIGBAQIQAAIRAQIRgQKRAIKRgQMRgIORgIOSEIOSEQOSEYQiEIQiEQQikQQikYQikhSikQSikYSjEYSjEhSjkhUjEYUjEhUjkhUjkpWjkpWkIpY0IpY0Ixa0oxc1JCe1JCe1pKhFpKhGNKjFpKjGNSlHNKnHNKrYxavYxr';
const hangerPixels =
  '';

export const EASEL_WIDTH = 37;
export const EASEL_HEIGHT = 102;
const easelPalette =
  '';
const easelPixels =
  '';

export const SINGLEBED_WIDTH = 66;
export const SINGLEBED_HEIGHT = 90;
const singleBedPalette =
  '';
const singleBedPixels =
  '';

export const DOUBLEBED_WIDTH = 85;
export const DOUBLEBED_HEIGHT = 143;
const doubleBedPalette =
  '';
const doubleBedPixels =
  '';

export const WATER_TROUGH_WIDTH = 67;
export const WATER_TROUGH_HEIGHT = 78;
const waterTroughPalette =
  '';
const waterTroughPixels =
  '';

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function decode(encoded: string): Uint8Array {
  const bytes = new Uint8Array(Math.floor((encoded.length * 3) / 4));
  let bits = 0,
    pending = 0,
    count = 0;
  for (const character of encoded) {
    if (character === '=') break;
    const digit = BASE64.indexOf(character);
    pending = (pending << 6) | digit;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes[count++] = (pending >>> bits) & 255;
    }
  }
  return bytes.subarray(0, count);
}

function fromPalette(width: number, height: number, palette: string, pixels: string): PixelImage {
  const image = new PixelImage(width, height);
  const colors = decode(palette);
  const indices = decode(pixels);
  for (let i = 0; i < width * height; i++) {
    const index = indices[i] ?? 0;
    if (!index) continue;
    const offset = i * 4;
    image.data[offset] = colors[index * 3] ?? 0;
    image.data[offset + 1] = colors[index * 3 + 1] ?? 0;
    image.data[offset + 2] = colors[index * 3 + 2] ?? 0;
    image.data[offset + 3] = 255;
  }
  return image;
}

export function drawPixelForge(size: 'small' | 'large'): PixelImage {
  return size === 'small'
    ? fromPalette(SMALL_FORGE_WIDTH, SMALL_FORGE_HEIGHT, smallPalette, smallPixels)
    : fromPalette(LARGE_FORGE_WIDTH, LARGE_FORGE_HEIGHT, largePalette, largePixels);
}

export function drawPixelSignHanger(mirrored = false): PixelImage {
  const image = fromPalette(HANGER_WIDTH, HANGER_HEIGHT, hangerPalette, hangerPixels);
  return mirrored ? image.mirrored() : image;
}

export function drawPixelEasel(mirrored = false): PixelImage {
  const image = fromPalette(EASEL_WIDTH, EASEL_HEIGHT, easelPalette, easelPixels);
  return mirrored ? image.mirrored() : image;
}

/** La referencia queda intacta si no se solicita una tintura. */
export function drawPixelBed(
  size: 'single' | 'double',
  mirrored = false,
  blanketColor?: readonly [number, number, number],
): PixelImage {
  const image =
    size === 'single'
      ? fromPalette(SINGLEBED_WIDTH, SINGLEBED_HEIGHT, singleBedPalette, singleBedPixels)
      : fromPalette(DOUBLEBED_WIDTH, DOUBLEBED_HEIGHT, doubleBedPalette, doubleBedPixels);
  if (blanketColor && size === 'double') {
    for (let y = 44; y < 111; y++)
      for (let x = 10; x < 76; x++) {
        const at = (y * image.width + x) * 4;
        const r = image.data[at] ?? 0,
          g = image.data[at + 1] ?? 0,
          b = image.data[at + 2] ?? 0;
        // Los grises neutros de la manta; la madera marrón y las sábanas claras no cambian.
        if (image.data[at + 3] !== 255 || r !== g || g !== b || r < 48 || r > 140) continue;
        const brightness = r / 100;
        image.data[at] = Math.min(255, Math.round(blanketColor[0] * brightness));
        image.data[at + 1] = Math.min(255, Math.round(blanketColor[1] * brightness));
        image.data[at + 2] = Math.min(255, Math.round(blanketColor[2] * brightness));
      }
  }
  return mirrored ? image.mirrored() : image;
}

export function drawPixelWaterTrough(mirrored = false): PixelImage {
  const image = fromPalette(
    WATER_TROUGH_WIDTH,
    WATER_TROUGH_HEIGHT,
    waterTroughPalette,
    waterTroughPixels,
  );
  return mirrored ? image.mirrored() : image;
}
